/* Bright street, compact corner instruments and captions outside the driving view. */
:root {
  --tar: #15110e; /* road tar, page ground */
  --paper: #f7efe0; /* text on dark */
  --newsprint: #f1e9d6; /* game-over newspaper */
  --ink: #1d1814; /* newspaper ink */
  --hood: #ffcb1f; /* rickshaw-hood yellow, the one loud colour */
  --led-pink: #ff3fa4; /* LED strip */
  --led-cyan: #2ee6ff; /* LED strip */
  --breaking: #e0242b; /* breaking-news red */
  --news-blue: #0f2b63; /* ticker band */
  --band: 34px; /* the news band's height; the buttons and the spoken line sit above it */
  --volt: #ff5b3a; /* seven-segment voltmeter */
  --scrim: rgba(10, 8, 6, 0.72);
  /* a rickshaw painter's garland: pink, cyan and yellow flowers on a green vine, one tile of three repeated sideways */
  --garland: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='30' viewBox='0 0 120 30'><defs><ellipse id='p' cy='-5.4' rx='3.6' ry='5.3'/><g id='f' stroke='%23fff' stroke-width='1.2'><use href='%23p'/><use href='%23p' transform='rotate(72)'/><use href='%23p' transform='rotate(144)'/><use href='%23p' transform='rotate(216)'/><use href='%23p' transform='rotate(288)'/></g><path id='l' d='M0 0C2 -5 8 -8 13 -6C10 -1 5 1 0 0Z'/></defs><path d='M0 15Q10 9 20 15T40 15T60 15T80 15T100 15T120 15' fill='none' stroke='%231f8a4c' stroke-width='2'/><g fill='%2337c46a' stroke='%23135c33' stroke-width='.8'><use href='%23l' x='0' y='15'/><use href='%23l' transform='translate(40 15)'/><use href='%23l' transform='translate(40 15) rotate(180)'/><use href='%23l' transform='translate(80 15)'/><use href='%23l' transform='translate(80 15) rotate(180)'/><use href='%23l' transform='translate(120 15) rotate(180)'/></g><use href='%23f' fill='%23ff3fa4' transform='translate(20 15)'/><circle cx='20' cy='15' r='2.6' fill='%23ffcb1f'/><use href='%23f' fill='%232ee6ff' transform='translate(60 15) rotate(36)'/><circle cx='60' cy='15' r='2.6' fill='%23ff3fa4'/><use href='%23f' fill='%23ffcb1f' transform='translate(100 15)'/><circle cx='100' cy='15' r='2.6' fill='%23e0242b'/><g fill='%23fff'><circle cx='40' cy='4' r='1.3'/><circle cx='80' cy='26' r='1.3'/><circle cx='0' cy='26' r='1.3'/><circle cx='120' cy='26' r='1.3'/></g></svg>");
  /* more of the rickshaw painter's kit: the fringe that hangs from a hood's edge (pink, cyan and yellow pennants on a
     red band), and a corner bouquet of three flowers */
  --fringe: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='72' height='16' viewBox='0 0 72 16'><rect width='72' height='3' fill='%23e0242b'/><path d='M0 3H24L12 15Z' fill='%23ff3fa4'/><path d='M24 3H48L36 15Z' fill='%232ee6ff'/><path d='M48 3H72L60 15Z' fill='%23ffcb1f'/><g fill='%23fff'><circle cx='12' cy='7.5' r='1.7'/><circle cx='36' cy='7.5' r='1.7'/><circle cx='60' cy='7.5' r='1.7'/></g></svg>");
  /* a thin line of the same fringe, for the maker's name (24 October 2026): a red band and pink, cyan and yellow pennants */
  --pennants: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='18' height='5' viewBox='0 0 18 5'><rect width='18' height='1' fill='%23e0242b'/><path d='M0 1H6L3 5Z' fill='%23ff3fa4'/><path d='M6 1H12L9 5Z' fill='%232ee6ff'/><path d='M12 1H18L15 5Z' fill='%23ffcb1f'/></svg>");
  /* the same line printed in the paper's red ink, for the paper's credit (bright pennants clashed with newsprint) */
  --pennants-ink: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='18' height='5' viewBox='0 0 18 5'><rect width='18' height='1' fill='%23b3121b'/><path d='M0 1H6L3 5Z' fill='%23b3121b'/><path d='M12 1H18L15 5Z' fill='%23b3121b'/><path d='M6 1H12L9 5Z' fill='%23b3121b' fill-opacity='.45'/></svg>");
  /* the maker's face beside his name: assets/site/omar-faruqe-riyad.jpg whole, painted like the film poster on the auto's
     back board (colours boosted, posterised to 3 bits, a warm tint), 72 px, JPEG quality 82, 1,679 bytes; inline, so the
     game asks no server for it. The owner picked this over a plain photo and a letter badge (24 October 2026): a face
     says a person made this, and invites a visit */
  --maker-face: url("data:image/jpeg;base64,");
  --bouquet: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='96' height='96' viewBox='0 0 96 96'><defs><ellipse id='p' cy='-6.6' rx='4.5' ry='6.6'/><g id='f' stroke='%23fff' stroke-width='1.4'><use href='%23p'/><use href='%23p' transform='rotate(72)'/><use href='%23p' transform='rotate(144)'/><use href='%23p' transform='rotate(216)'/><use href='%23p' transform='rotate(288)'/></g><path id='l' d='M0 0C3 -7 12 -12 20 -9C15 -2 8 1 0 0Z'/></defs><g fill='%2337c46a' stroke='%23135c33' stroke-width='1'><use href='%23l' transform='translate(50 28) rotate(168)'/><use href='%23l' transform='translate(70 50) rotate(122)'/><use href='%23l' transform='translate(78 48) rotate(78)'/><use href='%23l' transform='translate(64 20) rotate(205)'/><use href='%23l' transform='translate(84 30) rotate(72)'/></g><use href='%23f' fill='%23ff3fa4' transform='translate(78 18) scale(1.35)'/><circle cx='78' cy='18' r='3.6' fill='%23ffcb1f'/><use href='%23f' fill='%23ffcb1f' transform='translate(52 26) rotate(18) scale(1.05)'/><circle cx='52' cy='26' r='2.8' fill='%23e0242b'/><use href='%23f' fill='%232ee6ff' transform='translate(74 46) rotate(40) scale(1.05)'/><circle cx='74' cy='46' r='2.8' fill='%23ff3fa4'/><g fill='%23fff'><circle cx='60' cy='48' r='1.6'/><circle cx='88' cy='34' r='1.4'/><circle cx='40' cy='12' r='1.4'/></g></svg>");
  --f-display:
    "Baloo Da 2", "Anek Bangla", "Noto Sans Bengali", system-ui, sans-serif;
  --f-ui:
    "Anek Bangla", "Hind Siliguri", "Noto Sans Bengali", system-ui, sans-serif;
  --f-ticker:
    "Hind Siliguri", "Anek Bangla", "Noto Sans Bengali", system-ui, sans-serif;
  --f-news: "Tiro Bangla", "Noto Serif Bengali", Georgia, serif;
  --f-mono: "Share Tech Mono", ui-monospace, "Courier New", monospace;
  color-scheme: dark;
}
[hidden] {
  display: none !important;
}
html,
body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--tar);
  color: var(--paper);
  font-family: var(--f-ui);
}
#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: var(--tar);
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}
/* what scrolls (the menu, the paper, the help, the board's list, the cards) scrolls but never zooms: iPad Safari zoomed
   in on a double tap there, and back in the game, which blocks pinching, it could not be zoomed out (25 October 2026).
   manipulation first, for an older Safari that knows no pan-x pan-y */
#menu,
#paper,
.np-scroll,
.help,
.w-list {
  touch-action: manipulation;
  touch-action: pan-x pan-y;
}
#c {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}
button {
  font: inherit;
  color: inherit;
}
button:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 3px;
}

/* ---------- HUD ---------- */
#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.hud-top {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  padding: calc(env(safe-area-inset-top, 0px) + 12px) 16px 0;
}
.lbl {
  display: inline-block;
  font-size: 13px;
  letter-spacing: 0.06em;
  color: #fff;
  background: rgba(12, 10, 8, 0.6);
  padding: 1px 8px;
  border-radius: 999px;
}
#loss {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(30px, 5.4vw, 48px);
  line-height: 1;
  color: var(--hood);
  text-shadow:
    2px 2px 0 #ae2941,
    4px 4px 0 #14372f,
    0 0 16px rgba(0, 0, 0, 0.45);
  font-variant-numeric: tabular-nums;
}
#lossBox .lbl {
  background: rgba(20, 55, 47, 0.84);
  box-shadow: inset 0 0 0 1px rgba(255, 203, 31, 0.6);
}
.loss-row {
  display: flex;
  align-items: center;
  gap: 8px;
  transform-origin: left center;
}
#combo {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(18px, 3vw, 26px);
  color: #fff;
  background: var(--led-pink);
  padding: 2px 10px 0;
  border-radius: 8px;
  box-shadow: 0 3px 0 #000;
}
#battBox {
  text-align: right;
  display: grid;
  justify-items: end;
  gap: 4px;
}
.meter {
  background: #0b0908;
  border: 2px solid #3a332d;
  border-radius: 6px;
  padding: 2px 8px;
  box-shadow: inset 0 0 10px #000;
}
#volt {
  font-family: var(--f-mono);
  font-size: clamp(22px, 3.6vw, 30px);
  color: var(--volt);
  text-shadow: 0 0 8px rgba(255, 91, 58, 0.7);
  letter-spacing: 0.04em;
}
.bar {
  width: clamp(96px, 16vw, 150px);
  height: 8px;
  background: rgba(0, 0, 0, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 4px;
  overflow: hidden;
}
#battBar {
  display: block;
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, var(--volt), var(--hood));
  transition: width 0.2s;
}
#battWarn {
  font-weight: 800;
  color: #fff;
  background: var(--breaking);
  padding: 1px 8px;
  border-radius: 6px;
  animation: blink 0.6s steps(2) infinite;
}
@keyframes blink {
  50% {
    opacity: 0.25;
  }
}
#chargeNow {
  font-weight: 800;
  font-size: 14px;
  padding: 2px 10px 1px;
  border-radius: 999px;
  box-shadow: 0 2px 0 #000;
  white-space: nowrap;
}
#chargeNow.on {
  color: #062b14;
  background: #4dff95;
  animation: pulseGlow 1s ease-out infinite;
}
#chargeNow.on::before {
  content: "";
  display: inline-block;
  width: 9px;
  height: 13px;
  margin-right: 6px;
  vertical-align: -1px;
  background: #062b14;
  clip-path: polygon(62% 0, 0 56%, 44% 56%, 30% 100%, 100% 40%, 56% 40%);
}
@keyframes pulseGlow {
  0% {
    box-shadow:
      0 0 0 0 rgba(77, 255, 149, 0.75),
      0 2px 0 #000;
  }
  100% {
    box-shadow:
      0 0 0 12px rgba(77, 255, 149, 0),
      0 2px 0 #000;
  }
}
#chargeNow.stop {
  color: var(--ink);
  background: var(--hood);
}
#chargeNow.paid {
  color: #50112f;
  background: #ffd0e8;
}
#chargeHint {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 700;
  color: #fff;
  background: rgba(12, 10, 8, 0.78);
  border: 1.5px solid rgba(255, 212, 0, 0.7);
  border-radius: 999px;
  padding: 2px 10px 2px 7px;
  white-space: nowrap;
}
#chargeHint.bribe {
  border-color: rgba(255, 124, 195, 0.85);
}
/* the same arrow as the auto on the map, turned toward the target: straight up is straight ahead */
#hintArrow {
  flex: none;
  width: 16px;
  height: 18px;
  fill: #ff3fa4;
  stroke: #fff;
  stroke-width: 1.6;
  stroke-linejoin: round;
  transition: transform 0.25s;
}
#minimap {
  width: clamp(104px, 14vw, 140px);
  height: clamp(104px, 14vw, 140px);
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.4);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.45);
}
.hud-btns {
  display: flex;
  gap: 8px;
}
#muteBtn,
#pauseBtn {
  pointer-events: auto;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 1.5px solid rgba(255, 255, 255, 0.5);
  background: rgba(12, 10, 8, 0.6);
  border-radius: 50%;
  color: #fff;
  cursor: pointer;
}
#muteBtn svg {
  width: 22px;
  height: 22px;
}
#pauseBtn svg {
  width: 20px;
  height: 20px;
}
#muteBtn.off {
  color: #ff8f8f;
  border-color: rgba(255, 143, 143, 0.7);
}
/* the pause (src/game/pause.js): the loading screen's painted panel over the frozen street, and the ৩ ২ ১ before the run
   goes on, in the title's lettering */
#pause {
  position: absolute;
  inset: 0;
  z-index: 7;
  display: grid;
  place-items: center;
  background: rgba(10, 8, 6, 0.55);
}
#pause .card {
  display: grid;
  justify-items: center;
  gap: 12px;
  width: min(300px, 82vw);
  box-sizing: border-box;
  padding: 18px 18px 20px;
  border-radius: 16px;
  text-align: center;
  color: var(--paper);
  background: #14372f;
  border: 3px solid var(--hood);
  box-shadow:
    0 0 0 3px var(--tar),
    0 0 0 5px var(--led-pink),
    0 18px 50px rgba(0, 0, 0, 0.5);
}
#pause h2 {
  margin: 0;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: 34px;
  line-height: 1.15;
  color: var(--hood);
  text-shadow:
    2px 2px 0 #ae2941,
    4px 4px 0 #0b211c;
}
#pause p {
  margin: 0;
  font-size: 15px;
  opacity: 0.85;
}
#pause .row {
  display: flex;
  gap: 10px;
}
#pause .ghost {
  min-height: 44px;
  padding: 6px 14px;
  border-radius: 12px;
  border: 1.5px solid rgba(255, 255, 255, 0.45);
  background: rgba(0, 0, 0, 0.25);
  color: var(--paper);
  font: inherit;
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
}
#countdown {
  position: absolute;
  inset: 0;
  z-index: 7;
  display: grid;
  place-items: center;
  pointer-events: none;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(90px, 30vw, 170px);
  line-height: 1;
  color: var(--hood);
  text-shadow:
    4px 4px 0 #ae2941,
    8px 8px 0 #0b211c;
}
/* the first run of a visit: how to drive, for a few seconds, up top where the sky is */
#controls {
  position: absolute;
  left: 50%;
  top: calc(66px + env(safe-area-inset-top, 0px));
  transform: translateX(-50%);
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px 14px;
  width: max-content;
  max-width: min(640px, 92vw);
  box-sizing: border-box;
  padding: 8px 14px 9px;
  border-radius: 14px;
  background: rgba(12, 10, 8, 0.82);
  color: #fff;
  font-size: 14px;
  line-height: 1.4;
  pointer-events: none;
  transition: opacity 0.5s;
}
#controls .t {
  flex-basis: 100%;
  text-align: center;
  font-weight: 800;
  color: var(--hood);
  font-size: 13px;
}
#controls .row {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
}
#controls kbd {
  font-family: var(--f-mono);
  font-size: 12px;
  background: rgba(255, 255, 255, 0.14);
  border: 1px solid rgba(255, 255, 255, 0.45);
  border-bottom-width: 2px;
  border-radius: 5px;
  padding: 0 6px;
}
#controls.fade {
  opacity: 0;
}
#touch.teach .tbtn {
  animation: teach 1s ease-in-out infinite;
}
#touch.teach .tbtn[data-tip]::after {
  content: attr(data-tip);
  position: absolute;
  bottom: 5px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(12, 10, 8, 0.8);
  color: #fff;
  font-family: var(--f-ui);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.4;
  padding: 0 6px;
  border-radius: 999px;
  white-space: nowrap;
  pointer-events: none;
}
#touch.teach .tbtn[data-tip] svg {
  margin-bottom: 10px;
}
@keyframes teach {
  50% {
    box-shadow: 0 0 0 4px var(--hood);
  }
}
/* portrait stacks the pedals two by two: the lower row's tips would cover the upper buttons, and ব্রেক and চালান say what they do */

#alerts {
  position: absolute;
  left: 50%;
  top: calc(env(safe-area-inset-top, 0px) + 14px);
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  max-width: min(44vw, 420px);
}
#mobWarn {
  font-weight: 800;
  font-size: clamp(14px, 1.9vw, 18px);
  line-height: 1.25;
  color: #fff;
  background: rgba(196, 20, 32, 0.92);
  padding: 3px 12px 2px;
  border-radius: 999px;
  box-shadow: 0 2px 0 #000;
  animation: jitter 0.18s infinite;
  white-space: nowrap;
}
#mobWarn small {
  font-size: 0.82em;
  font-weight: 600;
  margin-left: 4px;
}
@keyframes jitter {
  0% {
    transform: translate(0, 0);
  }
  33% {
    transform: translate(-1px, 1px);
  }
  66% {
    transform: translate(1px, -1px);
  }
}
#wrongWay {
  font-weight: 800;
  font-size: clamp(13px, 1.7vw, 16px);
  color: var(--ink);
  background: var(--led-cyan);
  padding: 2px 10px;
  border-radius: 999px;
  box-shadow: 0 2px 0 #000;
  white-space: nowrap;
}
@media (max-width: 640px) {
  #alerts {
    left: 16px;
    transform: none;
    top: calc(env(safe-area-inset-top, 0px) + 92px);
    align-items: flex-start;
    max-width: 58vw;
  }
}
#vip {
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 800;
  font-size: clamp(13px, 1.7vw, 16px);
  color: #fff;
  background: rgba(120, 10, 30, 0.9);
  padding: 2px 10px 1px;
  border-radius: 999px;
  box-shadow: 0 2px 0 #000;
  white-space: nowrap;
}
#vipArrow {
  display: inline-block;
  color: var(--hood);
  transition: transform 0.15s;
}
/* the blockade ahead: breaking-news red, pulsing, with whether the road is shut or the road crew's ramp goes over it */
#blockade {
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 800;
  font-size: clamp(13px, 1.7vw, 16px);
  color: #fff;
  background: var(--breaking);
  padding: 2px 10px 1px;
  border-radius: 999px;
  box-shadow: 0 2px 0 #000;
  white-space: nowrap;
  animation: blockadePulse 1s ease-in-out infinite;
}
#blockade small {
  font-weight: 600;
  font-size: 0.86em;
  padding: 0 6px;
  border-left: 1px solid #fff8;
  border-right: 1px solid #fff8;
}
#blockadeArrow {
  display: inline-block;
  color: var(--hood);
  transition: transform 0.15s;
}
@keyframes blockadePulse {
  50% {
    box-shadow:
      0 2px 0 #000,
      0 0 0 5px rgba(224, 36, 43, 0.35);
  }
}
/* breaking news: the whole band turns red while the story is on it, as the TV channels do */
#ticker.breaking {
  background: linear-gradient(180deg, #e63a40 0%, #b8141c 48%, #6f070d 100%);
  border-top-color: #fff;
}
#ticker.breaking .tag.breaking {
  background: #fff;
  color: var(--breaking);
}
#ticker.breaking .tag.breaking::before {
  background: var(--breaking);
}
#vipDist {
  font-variant-numeric: tabular-nums;
}
#grade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(
    ellipse at center,
    transparent 75%,
    rgba(26, 52, 56, 0.08)
  );
}
/* the colour grade: a soft edge for each time of day (daylight.js sets <html data-time>). Plain see-through colour over
   the canvas, with no blend mode or filter, so it costs a phone nothing per frame. */
[data-time="afternoon"] #grade {
  background:
    linear-gradient(to bottom, rgba(255, 196, 120, 0.14), transparent 38%),
    radial-gradient(ellipse at center, transparent 62%, rgba(110, 64, 22, 0.16));
}
[data-time="dusk"] #grade {
  background:
    linear-gradient(to bottom, rgba(255, 120, 90, 0.12), transparent 42%),
    radial-gradient(ellipse at center, transparent 55%, rgba(58, 18, 44, 0.26));
}
[data-time="night"] #grade {
  background: radial-gradient(
    ellipse at center,
    transparent 48%,
    rgba(4, 6, 22, 0.42)
  );
}
#meme {
  position: absolute;
  inset: 0;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  text-align: center;
  padding: 16px;
  padding-block: calc(env(safe-area-inset-top, 0px) + 9vh)
    calc(env(safe-area-inset-bottom, 0px) + 13vh);
}
/* the bus death's caption over everything (the map and the buttons covered it), and the driving buttons dimmed under it:
   nothing can be driven while it shows */
#meme {
  z-index: 6;
}
#app:has(#meme:not([hidden])) #touch {
  opacity: 0.3;
  transition: opacity 0.25s;
}
#meme div {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(30px, 6.4vw, 70px);
  line-height: 1.05;
  color: #fff;
  max-width: 18ch;
  text-wrap: balance;
  -webkit-text-stroke: 2px #000;
  paint-order: stroke fill;
  text-shadow:
    4px 4px 0 #000,
    -2px -2px 0 #000,
    2px -2px 0 #000,
    -2px 2px 0 #000;
  animation: memeIn 0.35s cubic-bezier(0.2, 1.6, 0.4, 1) both;
}
#memeBot {
  animation-delay: 0.6s !important;
  color: var(--hood) !important;
}
@keyframes memeIn {
  from {
    transform: scale(2.2) rotate(-6deg);
    opacity: 0;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s;
  background: radial-gradient(
    ellipse at center,
    transparent 45%,
    rgba(224, 36, 43, 0.55) 100%
  );
}
#floaters {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}
.floater {
  position: absolute;
  left: 0;
  top: 0;
  white-space: nowrap;
  text-align: center;
  transform: translate(-50%, -50%);
  font-family: var(--f-display);
  font-weight: 800;
  line-height: 1;
  animation: floatUp 1.4s ease-out forwards;
}
.floater b {
  display: block;
  font-size: clamp(20px, 3vw, 30px);
  color: var(--hood);
  text-shadow:
    0 3px 0 #000,
    0 0 12px #000;
}
.floater span {
  display: block;
  font-size: clamp(13px, 1.8vw, 16px);
  font-weight: 700;
  color: #fff;
  margin-top: 2px;
  text-shadow:
    -1px -1px 0 #000,
    1px -1px 0 #000,
    -1px 1px 0 #000,
    1px 1px 0 #000,
    0 2px 4px #000;
} /* a full outline: readable on sky or white walls */
.floater.spent b {
  color: #ff7cc3;
}
.floater.nothing b {
  color: #c9c2b4;
} /* ৳০: a vehicle hit again pays nothing (G.wreckAgain) */
.floater.shout b {
  color: #fff;
  font-size: clamp(14px, 2vw, 19px);
  text-shadow:
    0 2px 0 var(--breaking),
    0 0 8px #000;
}
@keyframes floatUp {
  0% {
    opacity: 0;
    margin-top: 10px;
    scale: 0.6;
  }
  12% {
    opacity: 1;
    scale: 1.15;
  }
  25% {
    scale: 1;
  }
  100% {
    opacity: 0;
    margin-top: -70px;
  }
}

/* Messages live at the edges, never over a projected vehicle. */
/* ---------- the run's place, as a TV channel captions a live report: a red সরাসরি tag and the name (G.placeCard) ---------- */
#placeCard {
  position: absolute;
  left: 50%;
  top: 23%;
  transform: translateX(-50%);
  z-index: 3;
  display: flex;
  align-items: stretch;
  pointer-events: none;
  opacity: 0;
  white-space: nowrap;
  filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.35));
}
#placeCard.low {
  top: 33%;
}
@media (orientation: portrait) and (max-width: 759px) {
  #placeCard {
    top: 29%;
  }
} /* under the hint on a phone */
#placeCard .live {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 20px 0 12px;
  margin-right: -10px;
  position: relative;
  z-index: 1;
  background: var(--breaking);
  color: #fff;
  font-family: var(--f-ticker);
  font-weight: 700;
  font-size: 16px;
  clip-path: polygon(0 0, 100% 0, calc(100% - 13px) 100%, 0 100%);
}
#placeCard .live::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #fff;
  animation: onAir 1.6s ease-in-out infinite;
}
#placeCard .where {
  padding: 3px 20px 1px 24px;
  background: linear-gradient(
    180deg,
    #1c4796 0%,
    var(--news-blue) 48%,
    #081838 100%
  );
  border-bottom: 3px solid var(--hood);
  color: #fff;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(26px, 5vw, 40px);
  line-height: 1.25;
}

/* ---------- the TV news band along the bottom edge ---------- */
/* One item crawls through at a time, right to left, on a navy band under a yellow rule. The tag on the left says what
   kind of news it is: খবর (blue) for the day's other news, সর্বশেষ (amber) after something happens, ব্রেকিং (red) for the
   big moments; its light blinks like a studio's on-air lamp. The crawl is a transform animation, so it costs no layout. */
#ticker {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: calc(var(--band) + env(safe-area-inset-bottom, 0px));
  padding-bottom: env(safe-area-inset-bottom, 0px);
  box-sizing: border-box;
  display: flex;
  align-items: stretch;
  overflow: hidden;
  pointer-events: none;
  font-family: var(--f-ticker);
  background: linear-gradient(
    180deg,
    #1c4796 0%,
    var(--news-blue) 48%,
    #081838 100%
  );
  border-top: 2px solid var(--hood);
  box-shadow: 0 -3px 12px rgba(0, 0, 0, 0.3);
}
#ticker .tag {
  position: relative;
  z-index: 1;
  flex: none;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 22px 0 12px;
  margin-right: -10px;
  color: #fff;
  font-weight: 700;
  font-size: 15px;
  background: #2b5fc4;
  clip-path: polygon(0 0, 100% 0, calc(100% - 13px) 100%, 0 100%);
}
#ticker .tag::before {
  content: "";
  flex: none;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #ff5a64;
  animation: onAir 1.6s ease-in-out infinite;
}
#ticker .tag.latest {
  background: #df7a1c;
}
#ticker .tag.breaking {
  background: var(--breaking);
}
#ticker .tag.breaking::before {
  background: #fff;
}
@keyframes onAir {
  50% {
    opacity: 0.2;
  }
}
#ticker .track {
  flex: 1;
  min-width: 0;
  position: relative;
  overflow: hidden;
  color: #fff;
  font-weight: 700;
  font-size: 16px;
}
#ticker .item {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  white-space: nowrap;
  will-change: transform;
  text-shadow: 0 1px 1px rgba(0, 0, 0, 0.45);
}
#ticker .item::before {
  content: "◆";
  color: var(--hood);
  font-size: 0.6em;
  margin: 0 10px 0 4px;
}
/* the address at the band's right end, as a TV channel puts its own, so a screenshot or a phone filming a laptop carries it */
#ticker .url {
  flex: none;
  display: flex;
  align-items: center;
  padding: 0 12px 0 14px;
  border-left: 1px solid rgba(255, 255, 255, 0.22);
  background: rgba(0, 0, 0, 0.28);
  color: var(--hood);
  font-weight: 800;
  font-size: 14px;
  letter-spacing: 0.02em;
}
#ticker .item.still {
  right: 0;
  overflow: hidden;
  text-overflow: ellipsis;
} /* reduced motion: no crawl, a line at a time */
#dialogue,
#hint {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: max-content;
  box-sizing: border-box;
  max-width: min(480px, 88vw);
  padding: 6px 14px;
  border-radius: 9px;
  background: rgba(255, 249, 237, 0.46);
  color: #1d2f2b;
  font-size: 17px;
  font-weight: 700;
  text-align: center;
  pointer-events: none;
  text-shadow:
    0 0 6px rgba(255, 252, 244, 0.9),
    0 0 2px rgba(255, 252, 244, 0.9);
} /* see-through: a soft halo keeps the letters readable over any background */
#dialogue {
  bottom: calc(var(--band) + 22px + env(safe-area-inset-bottom, 0px));
}
#hint {
  top: calc(72px + env(safe-area-inset-top, 0px));
}
#floaters {
  top: calc(94px + env(safe-area-inset-top, 0px));
  left: 16px;
  right: auto;
  bottom: auto;
  width: 165px;
  height: 55px;
} /* just under the score, which ends at about 90px */
.floater {
  position: relative;
  transform: none;
  text-align: left;
  white-space: normal;
  animation: scoreFade 1.5s ease-out forwards;
}
.floater b {
  font-size: 21px;
}
.floater span {
  font-size: 12px;
}
@keyframes scoreFade {
  0% {
    opacity: 0;
    translate: 0 5px;
  }
  15%,
  70% {
    opacity: 1;
    translate: 0 0;
  }
  100% {
    opacity: 0;
    translate: 0 -6px;
  }
}
/* Phone controls: dark see-through glass, with no blur (re-blurring the moving road under the buttons every frame cost a
   phone dearly). Left thumb: the round arrows, with the two taps above them (হর্ন and শব্দবোমা), out of the way of steering.
   Right thumb: a big চালান in the corner, where the thumb rests, টান above it and ব্রেক beside it, along the thumb's arc.
   চালান is held nearly the whole run; until 27 October 2026 it sat above ব্রেক, its middle about 190 px up on a phone, and
   the owner found holding it there hurt and put the hand over the road. A thumb may slide from one button to the next
   without lifting (see initInput). Icons and short labels, a coloured glow while held.
   Players found them small (24 October 2026): they grow with the screen (--steer, the arrows), and each one answers a
   little beyond its edge (initTouch), so the drawn size is no longer all there is to hit. */
#touch {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc(var(--band) + 12px + env(safe-area-inset-bottom, 0px));
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding: 0 max(12px, env(safe-area-inset-right, 0px)) 0
    max(12px, env(safe-area-inset-left, 0px));
  pointer-events: none;
  --steer: min(78px, 19.5vw);
} /* clear of a notch on its side */
#touch .grp {
  display: flex;
  gap: 12px;
}
#touch .left {
  flex-direction: column;
  align-items: center;
}
#touch .row {
  display: flex;
  gap: 10px;
}
#touch .right {
  display: grid;
  grid-template-areas: ". boost" "brake gas";
  align-items: end;
  justify-items: center;
  gap: 10px 8px;
}
#touch .pedalcol {
  display: contents;
}
#tBoost {
  grid-area: boost;
}
#tGas {
  grid-area: gas;
}
#tBrake {
  grid-area: brake;
}
.tbtn {
  position: relative;
  display: grid;
  place-items: center;
  padding: 0;
  color: #fff;
  font-family: var(--f-display);
  font-weight: 800;
  white-space: nowrap;
  border: 1.5px solid rgba(255, 255, 255, 0.4);
  background: rgba(14, 18, 20, 0.42);
  box-shadow:
    0 6px 18px rgba(0, 0, 0, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
  touch-action: none;
  pointer-events: auto;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
  transition:
    transform 0.07s,
    background 0.12s,
    box-shadow 0.12s,
    opacity 0.2s;
}
.tbtn svg {
  width: 28px;
  height: 28px;
  pointer-events: none;
}
.tbtn span {
  pointer-events: none;
}
.tbtn.on {
  transform: scale(0.93);
}
.tbtn.round {
  width: var(--steer);
  height: var(--steer);
  border-radius: 50%;
}
.tbtn.round svg {
  width: 34px;
  height: 34px;
}
.tbtn.round.on {
  background: rgba(255, 255, 255, 0.3);
}
.tbtn.chip {
  width: 62px;
  height: 46px;
  border-radius: 15px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 2px;
  font-size: 10.5px;
  line-height: 1;
}
.tbtn.chip svg {
  width: 19px;
  height: 19px;
}
#tHorn.on {
  background: rgba(255, 255, 255, 0.32);
}
#tBomb {
  color: #ff9b7d;
  border-color: rgba(255, 112, 82, 0.72);
}
#tBomb span {
  color: #fff;
}
#tBomb.on {
  background: rgba(228, 68, 38, 0.62);
  box-shadow: 0 0 18px rgba(255, 92, 52, 0.75);
  color: #fff;
}
#tBomb.cool {
  opacity: 0.45;
}
/* টান is hit again and again, often in a hurry (the mob, a bus, the run-up to the cart), so it is 72 px, about 12 mm under
   a thumb: it was 64 until 27 October 2026, the smallest of the right thumb's buttons */
#tBoost {
  width: min(72px, 18vw);
  height: min(72px, 18vw);
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  color: #ffb02e;
  border-color: rgba(255, 176, 46, 0.75);
  font-size: 12px;
  line-height: 1;
}
#tBoost svg {
  width: 25px;
  height: 25px;
}
#tBoost span {
  color: #fff;
  margin-top: 1px;
}
#tBoost.on {
  background: #e88028;
  box-shadow: 0 0 18px rgba(255, 150, 0, 0.8);
  color: #fff;
}
.pedal {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 1px;
  border-radius: 18px;
  font-size: 14px;
}
.pedal svg {
  width: 32px;
  height: 32px;
}
#tGas svg {
  color: #6ff0b0;
}
#tBrake svg {
  color: #ff8a96;
}
.pedal.on {
  transform: scale(0.95) translateY(2px);
}
/* in the corner চালান's touches run to the screen's right and bottom edges, so its drawn width matters less than how far
   the thumb has to reach past it to ব্রেক: 92 px (104 for a day, 27 October 2026, and the owner's thumb missed ব্রেক) */
#tGas {
  width: min(92px, 23vw);
  height: 120px;
  border-radius: 24px;
  border-color: rgba(70, 230, 150, 0.85);
  font-size: 15px;
}
#tGas.on {
  background: rgba(40, 200, 120, 0.6);
  box-shadow: 0 0 20px rgba(60, 240, 150, 0.75);
}
#tBrake {
  width: min(80px, 18.5vw);
  height: 74px;
  border-color: rgba(255, 92, 108, 0.8);
} /* taller than at first (58, then 66), as the owner and players asked; narrower beside চালান, so a 360 px phone keeps a gap after → */
#tBrake.on {
  background: rgba(220, 40, 60, 0.62);
  box-shadow: 0 0 18px rgba(255, 60, 80, 0.7);
}
#hud.boosting .bar {
  box-shadow: 0 0 0 2px #e88028;
}
/* ---------- menu ---------- */
#menu {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: 16px;
  padding-block: calc(env(safe-area-inset-top, 0px) + 16px)
    calc(env(safe-area-inset-bottom, 0px) + 56px);
  background: linear-gradient(
    to top,
    rgba(10, 8, 6, 0.92) 0%,
    rgba(10, 8, 6, 0.55) 45%,
    rgba(10, 8, 6, 0) 75%
  );
  overflow: auto;
}
.menu-card {
  max-width: 600px;
  display: grid;
  gap: 14px;
  margin-top: auto;
} /* bottom-aligned, but scrolls from the top when the window is short */
.garland {
  display: block;
  height: 26px;
  width: min(364px, 84%);
  background: var(--garland) left center / 104px 26px round no-repeat;
} /* round: whole tiles, never a cut flower */
h1.title {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(52px, min(15vw, 14vh), 132px);
  line-height: 0.85;
  margin: 0;
  color: var(--hood);
  text-shadow:
    5px 5px 0 var(--led-pink),
    10px 10px 0 #000;
  text-wrap: balance;
}
.title-en {
  font-family: var(--f-display);
  font-weight: 600;
  font-size: clamp(15px, 2.4vw, 19px);
  letter-spacing: 0.3em;
  text-transform: uppercase;
  opacity: 0.8;
  margin-top: -4px;
}
/* the maker's credit, small in the menu's corner, out of the card's way (the owner's name, 22 October 2026) */
.credit {
  position: absolute;
  right: 16px;
  bottom: calc(env(safe-area-inset-bottom, 0px) + 7px);
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 4px 2px 1px;
  font-size: 13px;
  line-height: 1.2;
  color: rgba(255, 255, 255, 0.75);
  text-decoration: none;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.7);
}
/* the guide and the disclaimer, opened from quiet links in the menu's other corner (the owner kept the disclaimer off the
   paper, 25 October 2026; the guide, 29 October 2026, is the game's page of words for search engines and new players) */
.menu-note {
  position: absolute;
  left: 16px;
  bottom: calc(env(safe-area-inset-bottom, 0px) + 7px);
  margin: 0;
  font-size: 13px;
  line-height: 1.2;
  color: rgba(255, 255, 255, 0.75);
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.7);
}
.menu-note a {
  display: inline-block;
  padding: 4px 2px 1px;
  color: inherit;
  text-decoration: underline dotted rgba(255, 255, 255, 0.5);
  text-underline-offset: 3px;
}
.menu-note a:hover,
.menu-note a:focus-visible {
  color: #fff;
}
.menu-note a:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 2px;
}
.credit b {
  position: relative;
  font-weight: 800;
  color: #fff;
} /* the name stands out from "Made by" (the owner asked, 24 October 2026) */
.credit b::after,
.np-credit b::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -5px;
  height: 5px;
  background: var(--pennants) 0 0 / 18px 5px repeat-x;
} /* drawn below, so nothing moves */
.credit:hover b,
.credit:focus-visible b {
  color: var(--hood);
}
.credit .face,
.np-credit .face {
  flex: none;
  width: 20px;
  height: 20px;
  margin-right: 5px;
  border-radius: 50%;
  background: var(--maker-face) center / cover;
  box-shadow:
    0 0 0 1.5px var(--hood),
    0 0 0 3px var(--led-pink);
} /* a rickshaw-yellow ring edged in pink */
.credit svg {
  width: 9px;
  height: 9px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
} /* ↗: it opens elsewhere */
.credit:hover,
.credit:focus-visible {
  color: #fff;
}
/* the game's address under its name (28 October 2026: news pieces showed the game without it), and the sign-up line */
.menu-url {
  margin: 4px 0 0;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(16px, 2.4vw, 21px);
  letter-spacing: 0.02em;
  color: var(--hood);
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6);
}
.menu-sub {
  margin: 0;
  font-size: 12.5px;
  color: rgba(255, 255, 255, 0.85);
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.55);
}
.menu-sub .linkish {
  color: #fff;
}
.tagline {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(22px, 4.4vw, 34px);
  line-height: 1.1;
  margin: 0;
  color: #fff;
  text-wrap: balance;
}
.how {
  margin: 0;
  font-size: 17px;
  line-height: 1.55;
  max-width: 48ch;
}
.how em {
  font-style: normal;
  color: var(--hood);
  font-weight: 600;
  display: block;
  text-wrap: balance;
}
.how em span {
  display: inline-block;
} /* it breaks after the colon, never inside a phrase */
.how .dup {
  display: block;
}
.tagline,
.how {
  text-shadow:
    0 1px 3px rgba(0, 0, 0, 0.55),
    0 0 12px rgba(0, 0, 0, 0.25);
} /* readable over a bright street too */
.how-en {
  margin: -6px 0 0;
  font-size: 14px;
  line-height: 1.5;
  opacity: 0.7;
  max-width: 52ch;
}
.play-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 20px;
}
/* ডাউনলোড on the menu (INSTALL.menu): the game on the home screen, offered where players look first (the owner,
   24 October 2026: people could not find the paper's install button). An icon only, small and round beside
   রাস্তায় নামেন, which stays the first choice (the owner wanted it not to take the focus): dark glass, a thin
   rickshaw-yellow ring and the download arrow everyone knows (the owner's pick over a phone icon); 44 px, the smallest
   a thumb is sure of. On a computer too, where the browser can install the game (Chrome, Edge) */
/* the play button's dark little sibling: its corners, black edge and dark-yellow step, quieter inside */
.menu-install {
  display: inline-grid;
  place-items: center;
  width: 48px;
  height: 48px;
  box-sizing: border-box;
  padding: 0;
  margin-bottom: 5px;
  border: 2.5px solid var(--hood);
  border-radius: 12px;
  background: var(--ink);
  box-shadow:
    0 5px 0 #9c7400,
    0 0 0 2px #000;
  cursor: pointer;
  transition: transform 0.08s;
}
.menu-install svg {
  width: 24px;
  height: 24px;
  fill: none;
  stroke: var(--hood);
  stroke-width: 2.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.menu-install:active {
  transform: translateY(3px);
  box-shadow:
    0 2px 0 #9c7400,
    0 0 0 2px #000;
}
.menu-install:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 2px;
}
.menu-install-how {
  flex-basis: 100%;
  margin: 0;
  padding: 7px 10px;
  font-size: 14px;
  line-height: 1.45;
  color: #fff;
  background: rgba(12, 10, 8, 0.62);
  border-left: 4px solid var(--hood);
  border-radius: 4px;
}
.cta {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: 30px;
  line-height: 1;
  padding: 14px 30px 10px;
  border: 0;
  border-radius: 14px;
  background: var(--hood);
  color: var(--ink);
  box-shadow:
    0 6px 0 #9c7400,
    0 0 0 3px #000;
  cursor: pointer;
  transition: transform 0.08s;
}
.cta:active {
  transform: translateY(4px);
  box-shadow:
    0 2px 0 #9c7400,
    0 0 0 3px #000;
}
.best {
  font-size: 15px;
  opacity: 0.85;
}
.keys {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 8px;
  font-size: 13px;
  line-height: 1.6;
}
.keys .k {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px 2px 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
}
/* the rules as five short lines with a badge each, not a paragraph */
.rules {
  list-style: none;
  margin: 6px 0 12px;
  padding: 0;
  display: grid;
  gap: 8px;
}
.rules li {
  display: grid;
  grid-template-columns: 34px 1fr;
  gap: 10px;
  align-items: center;
}
.rules .ic {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  font-size: 18px;
  font-weight: 800;
}
.rules .ic.bus {
  background: rgba(255, 40, 40, 0.35);
}
.rules .ic.volt {
  background: #ffd400;
  color: #111;
}
.rules .ic.volt svg {
  width: 62%;
  height: 62%;
}
.rules .ic.tk {
  background: #ed71b6;
  color: #231121;
}
.rules strong {
  display: block;
  font-size: 15px;
  line-height: 1.3;
  color: var(--hood);
}
.rules span {
  font-size: 13.5px;
  line-height: 1.4;
  opacity: 0.92;
}
.help .keys-note {
  font-size: 13px;
  line-height: 1.5;
  opacity: 0.75;
  margin: 8px 0 0;
}
.keys kbd {
  font-family: var(--f-mono);
  font-size: 12px;
  border: 1px solid rgba(255, 255, 255, 0.35);
  border-bottom-width: 2px;
  border-radius: 4px;
  padding: 0 5px;
}

/* ---------- newspaper ---------- */
#paper {
  position: absolute;
  inset: 0;
  overflow: auto;
  background: rgba(0, 0, 0, 0.7);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 16px;
  padding-block: calc(env(safe-area-inset-top, 0px) + 16px)
    calc(env(safe-area-inset-bottom, 0px) + 56px);
}
.np {
  background:
    radial-gradient(
      ellipse at 50% 38%,
      transparent 58%,
      rgba(120, 88, 36, 0.13) 100%
    ),
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 .36  0 0 0 0 .26  0 0 0 0 .12  0 0 0 .07 0'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>"),
    var(--newsprint);
  color: var(--ink);
  width: 100%;
  max-width: 900px;
  padding: 14px 20px 20px;
  font-family: var(--f-news);
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.6);
  transform: rotate(-1.2deg);
  animation: paperIn 0.55s cubic-bezier(0.2, 1.3, 0.4, 1);
}
@keyframes paperIn {
  from {
    transform: rotate(-14deg) scale(0.4);
    opacity: 0;
  }
  to {
    transform: rotate(-1.2deg) scale(1);
    opacity: 1;
  }
}
.np header {
  text-align: center;
  border-bottom: 4px double var(--ink);
  padding-bottom: 6px;
}
.np-name {
  font-family: var(--f-news);
  font-size: clamp(34px, 7vw, 54px);
  line-height: 1;
}
/* a front page's furniture: the two ears beside the masthead (where a real paper keeps the weather), a red kicker over
   the headline, the dateline in bold, and the grain and aged edges of newsprint */
.np-mast {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 12px;
}
.np-ear {
  margin: 0;
  justify-self: start;
  display: grid;
  padding: 3px 9px 2px;
  border: 1.5px solid var(--ink);
  font-family: var(--f-ui);
  line-height: 1.15;
  text-align: center;
}
.np-ear:last-child {
  justify-self: end;
}
.np-ear small {
  font-size: 11px;
  font-weight: 600;
  opacity: 0.75;
}
.np-ear b {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: 15px;
  color: #b3121b;
}
.np-kicker {
  margin: 10px 0 -4px;
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: 14px;
  line-height: 1.2;
  color: #b3121b;
}
.np-kicker::before {
  content: "";
  width: 10px;
  height: 10px;
  background: #b3121b;
}
.np-cols p b {
  font-weight: 700;
}
.np-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 13px;
  border-top: 1px solid var(--ink);
  margin-top: 8px;
  padding-top: 4px;
}
.np h2 {
  font-size: clamp(24px, 4.4vw, 36px);
  line-height: 1.15;
  margin: 10px 0 12px;
  text-wrap: balance;
}
/* a front page: the photo beside the story on wide screens, stacked on narrow ones */
/* wide: the photo on the left; on the right the clipping, then the quote and the story. Narrow: one column in that order */
.np-body {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
  grid-template-areas: "photo buy" "photo story";
  grid-template-rows: auto 1fr;
  column-gap: 18px;
  row-gap: 12px;
  align-items: start;
}
.np-left {
  grid-area: photo;
}
.np-buy {
  grid-area: buy;
}
.np-right {
  grid-area: story;
  align-self: stretch;
}
.np-body figure {
  margin: 0;
}
.np img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  background: #999;
  border: 1px solid rgba(0, 0, 0, 0.35);
  filter: brightness(1.12) contrast(1.04) saturate(0.82) sepia(0.12);
} /* a slightly faded colour print, like a Dhaka front page */
.np figcaption {
  font-size: 12px;
  margin-top: 4px;
  font-style: italic;
}
.np-left,
.np-right,
.np-buy {
  min-width: 0;
}
.np-right,
.np-buy {
  border-left: 1px solid rgba(0, 0, 0, 0.25);
  padding-left: 16px;
}
.np-buy {
  padding-top: 13px;
  margin-bottom: -12px;
  padding-bottom: 12px;
} /* room for the clipping's tab; the rule runs on unbroken into the story */
.np-cols {
  font-size: 15px;
  line-height: 1.5;
}
.np-cols p {
  margin: 0 0 8px;
}
/* the shareable pieces: the loss stamped on the photo, what it would have bought, the quote */
.np-photo {
  position: relative;
}
.np-stamp {
  position: absolute;
  right: 10px;
  bottom: 10px;
  transform: rotate(-4deg);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 3px 12px 1px;
  background: rgba(241, 233, 214, 0.94);
  border: 3px solid #b3121b;
  color: #b3121b;
  font-family: var(--f-display);
  font-weight: 800;
  line-height: 1.05;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);
}
.np-stamp small {
  font-size: 13px;
}
.np-stamp b {
  font-size: clamp(22px, 3.4vw, 30px);
}
/* এই টাকায় হতো: a clipping to cut out and keep (a dashed edge, scissors on the corner), the comparison in bold with its
   quantity in red, and the real figure under it in small type: the figure is what makes the joke land */
.np-price {
  position: relative;
  margin-top: 0;
  padding: 13px 14px 8px;
  border: 2px dashed rgba(29, 24, 20, 0.5);
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.32);
}
.np-price span {
  position: absolute;
  left: 10px;
  top: -13px;
  padding: 3px 9px 1px;
  background: #b3121b;
  color: #fff;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: 14px;
  line-height: 1.3;
  white-space: nowrap;
  transform: rotate(-1.5deg);
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.2);
}
.np-price::after {
  content: "";
  position: absolute;
  right: 10px;
  top: -11px;
  width: 30px;
  height: 20px;
  background: var(--newsprint)
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='-12 -10 26 20'><g fill='none' stroke='%231d1814' stroke-width='2.2' stroke-linecap='round'><circle cx='-7' cy='-5' r='4'/><circle cx='-7' cy='5' r='4'/><path d='M-3.5 -3L12 4M-3.5 3L12 -4'/></g></svg>")
    center / 24px 18px no-repeat;
}
.np-price small {
  display: block;
  margin-top: 2px;
  font-family: var(--f-news);
  font-size: 12.5px;
  line-height: 1.35;
  opacity: 0.75;
}
.np-price small:empty {
  display: none;
}
/* a friend's challenge (CHALLENGE): on the menu, in the score's label, and how it went on the paper */
.dare {
  margin: 0;
  padding: 6px 12px 4px;
  border-radius: 10px;
  background: rgba(255, 63, 164, 0.2);
  border: 2px solid var(--led-pink);
  font-weight: 700;
  font-size: 17px;
  line-height: 1.35;
}
.dare b {
  color: var(--hood);
  font-family: var(--f-display);
  font-size: 1.15em;
}
#target {
  margin-left: 6px;
  opacity: 0.85;
}
#target.won {
  color: #6ff0b0;
  opacity: 1;
}
.np-dare {
  margin: 8px 0 0;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: 16px;
  color: #a0217a;
}
.np-price b {
  display: block;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(19px, 2.6vw, 24px);
  line-height: 1.25;
  color: var(--ink);
  text-wrap: balance;
}
.np-price b em {
  font-style: normal;
  color: #b3121b;
}
.np-quote {
  position: relative;
  margin: 2px 0 10px;
  padding-left: 30px;
}
.np-quote::before {
  content: "“";
  position: absolute;
  left: 0;
  top: -12px;
  font-size: 56px;
  line-height: 1;
  color: #b3121b;
}
.np-quote p {
  margin: 0;
  font-size: 19px;
  font-weight: 700;
  line-height: 1.3;
}
.np-quote cite {
  display: block;
  margin-top: 3px;
  font-size: 13px;
}
@media (max-width: 760px) {
  .np-body {
    grid-template-columns: 1fr;
    grid-template-areas: "photo" "buy" "story";
    grid-template-rows: auto;
    gap: 10px;
  }
  .np-buy {
    border-left: 0;
    padding: 4px 0 0;
    margin: 0;
  }
  .np img {
    aspect-ratio: 16 / 9;
  }
  .np-right {
    border-left: 0;
    padding-left: 0;
  }
}
.np-foot {
  margin: 10px 0 0;
  padding-top: 8px;
  border-top: 1px solid var(--ink);
  font-size: 14px;
  line-height: 1.5;
  font-style: italic;
}
/* a patron's line (sponsor.js), only when the owner has one: the brand in a yellow chip, a logo if it sent one */
.np-patron {
  margin: 8px 0 0;
  padding: 6px 0;
  border-top: 1px solid var(--ink);
  border-bottom: 1px solid var(--ink);
  text-align: center;
  font-size: 14px;
  font-weight: 700;
  line-height: 1.6;
}
.np-patron-mark {
  display: inline-flex;
  align-items: center;
  margin-left: 6px;
  padding: 1px 12px;
  border: 1.5px dashed var(--ink);
  background: #ffd400;
  font-weight: 800;
  vertical-align: middle;
}
.np-patron-mark img {
  display: block;
  height: 24px;
  width: auto;
}
.np-imprint {
  margin: 5px 0 0;
  font-size: 11.5px;
  line-height: 1.3;
  text-align: center;
  opacity: 0.7;
} /* a real paper's imprint line */
.np-imprint a {
  color: inherit;
  font-weight: 700;
  text-decoration: underline dotted;
  text-underline-offset: 2px;
} /* the editor's name opens the editor's page */
.np-imprint a:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 2px;
}
.np-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 18px;
  margin: 16px -20px -20px;
  padding: 12px 20px 14px;
  font-family: var(--f-ui);
  position: sticky;
  bottom: -16px;
  background: var(--newsprint);
  border-top: 1px solid rgba(0, 0, 0, 0.2);
}
.np-actions .best {
  opacity: 1;
}
.np-actions .share {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: 22px;
  line-height: 1;
  min-height: 48px;
  padding: 12px 18px 8px;
  border: 3px solid var(--ink);
  border-radius: 12px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}
.np-actions .share:active {
  transform: translateY(2px);
}
/* দৈনিক যানজট's list (SUBSCRIBE): a quiet line under the paper's record, and a subscription coupon
   over everything. Text fields need their own user-select: the game turns selection off, and iPhones then refuse typing. */
.linkish {
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  font-weight: 700;
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}
.np-subline {
  flex-basis: 100%;
  margin: -4px 0 0;
  font-family: var(--f-ui);
  font-size: 14px;
  line-height: 1.4;
} /* under the record, not in the paper */
.np-subline .linkish {
  color: #b3121b;
}
#subscribe {
  position: absolute;
  inset: 0;
  z-index: 15;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: auto;
  background: rgba(10, 8, 6, 0.62);
  padding: calc(env(safe-area-inset-top, 0px) + 16px)
    max(16px, env(safe-area-inset-right, 0px))
    calc(env(safe-area-inset-bottom, 0px) + 16px)
    max(16px, env(safe-area-inset-left, 0px));
  touch-action: manipulation;
  touch-action: pan-x pan-y;
  user-select: text;
  -webkit-user-select: text;
}
.sub-card {
  position: relative;
  width: 100%;
  max-width: 440px;
  box-sizing: border-box;
  margin: auto;
  display: grid;
  gap: 10px;
  padding: 24px 20px 16px;
  background: var(--newsprint);
  color: var(--ink);
  border: 2px dashed rgba(29, 24, 20, 0.5);
  border-radius: 4px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
  font-family: var(--f-ui);
}
.sub-tab {
  position: absolute;
  left: 12px;
  top: -13px;
  padding: 3px 9px 1px;
  background: #b3121b;
  color: #fff;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: 14px;
  line-height: 1.3;
  transform: rotate(-1.5deg);
}
.sub-card h2 {
  margin: 0;
  padding-right: 30px;
  font-family: var(--f-news);
  font-weight: 700;
  font-size: 26px;
  line-height: 1.3;
}
.sub-lead {
  margin: 0;
  font-size: 16px;
  line-height: 1.5;
}
.sub-label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
} /* read out, not shown: the field says what it is */
.sub-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
#subEmail {
  flex: 1 1 200px;
  min-width: 0;
  min-height: 48px;
  box-sizing: border-box;
  padding: 10px 12px;
  border: 2px solid var(--ink);
  border-radius: 10px;
  background: #fffdf7;
  color: var(--ink);
  font:
    16px/1.2 system-ui,
    -apple-system,
    "Segoe UI",
    sans-serif;
  user-select: text;
  -webkit-user-select: text;
} /* 16px: smaller, and an iPhone zooms in */
#subEmail:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 2px;
}
#subSend {
  flex: 0 0 auto;
  font-size: 20px;
  min-height: 48px;
  padding: 12px 18px 9px;
  box-shadow:
    0 4px 0 #9c7400,
    0 0 0 2px #000;
}
#subSend:disabled {
  opacity: 0.6;
}
.sub-hp {
  position: absolute;
  left: -9999px;
  width: 1px;
  height: 1px;
  opacity: 0;
} /* the field only a bot fills */
.sub-say {
  margin: 0;
  min-height: 1.4em;
  font-size: 15px;
  line-height: 1.45;
  font-weight: 600;
  color: #2f6b45;
}
.sub-say.bad {
  color: #b3121b;
}
.sub-say:empty {
  min-height: 0;
}
.sub-ok {
  display: none;
  justify-self: start;
  font-size: 20px;
  padding: 11px 22px 8px;
}
.sub-card.done .sub-row,
.sub-card.done .sub-label {
  display: none;
}
.sub-card.done .sub-ok {
  display: inline-block;
}
.sub-fine {
  margin: 0;
  font-size: 13px;
  opacity: 0.8;
}
.sub-fine a {
  color: inherit;
}
.sub-x {
  position: absolute;
  right: 6px;
  top: 4px;
  width: 44px;
  height: 44px;
  border: 0;
  background: none;
  color: var(--ink);
  font-size: 28px;
  line-height: 1;
  cursor: pointer;
}
.sub-x:focus-visible,
.linkish:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 2px;
}
/* মোস্ট ওয়ান্টেড (WANTED): a small poster tag in the menu's top corner, a line on the paper beside the list's offer,
   and the board itself as a police wanted poster over everything */
/* the menu's top corner: the game's Facebook page (the owner's, 23 October 2026), its YouTube channel (27 October 2026,
   the same button in YouTube's red) and মোস্ট ওয়ান্টেড, side by side. Not yt-* or *-youtube: social-blocking lists hide those */
.menu-corner {
  position: absolute;
  right: 14px;
  top: calc(env(safe-area-inset-top, 0px) + 14px);
  display: flex;
  align-items: center;
  gap: 10px;
}
.fb-page,
.menu-tube {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  box-sizing: border-box;
  border: 2px solid var(--ink);
  border-radius: 50%;
  background: #1877f2;
  color: #fff;
  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.35);
}
.menu-tube {
  background: #e00000;
} /* a shade under YouTube's own red, so white text on it stays readable */
.fb-page svg,
.menu-tube svg {
  width: 22px;
  height: 22px;
  fill: currentColor;
}
.fb-label,
.tube-label {
  display: none;
}
.fb-page:active,
.menu-tube:active {
  transform: translateY(2px);
}
.fb-page:focus-visible,
.menu-tube:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 2px;
}
.wanted-tag {
  min-height: 40px;
  padding: 8px 14px 5px;
  border: 2px solid var(--ink);
  border-radius: 4px;
  background: var(--newsprint);
  color: #b3121b;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: 16px;
  line-height: 1.1;
  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.35);
  transform: rotate(2deg);
  cursor: pointer;
}
.wanted-tag:active {
  transform: rotate(2deg) translateY(2px);
}
.wanted-tag:focus-visible,
.w-tabs button:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 2px;
}
#npLines {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  column-gap: 6px;
}
#npLines:not(:has(> :not([hidden]))) {
  display: none;
}
#npWanted:not([hidden]) ~ #npSubLine:not([hidden])::before {
  content: "· ";
}
/* the maker, on the paper every run ends on (the menu's corner was easy to miss: a player asked where the developer
   was, 23 October 2026); at the right end of the line on a laptop, so the paper does not grow */
.np-credit {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 12.5px;
  color: var(--ink);
  opacity: 0.8;
  white-space: nowrap;
  text-decoration: none;
}
.np-credit b {
  position: relative;
  font-weight: 800;
}
.np-credit b::after {
  bottom: -4px;
  height: 4px;
  background-image: var(--pennants-ink);
  background-size: 14.4px 4px;
}
.np-credit .face {
  width: 18px;
  height: 18px;
}
.np-credit svg {
  width: 9px;
  height: 9px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.np-credit:hover,
.np-credit:focus-visible {
  opacity: 1;
}
.np-credit:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 2px;
}
/* a phone has a second copy on the record's line instead (the owner keeps the phone's button area under 175 px) */
.np-record {
  display: contents;
}
.np-credit-phone {
  display: none;
}
/* the name, asked on the paper itself when a run makes the poster's top 20 and the phone has none (the owner found the
   board full of অজ্ঞাতনামা চালক); one ask at a time, so the list's offer steps aside while it shows. 30 px tall on a
   laptop, so the line is barely taller and a 930x675 paper still fits; 40 px on a phone */
.np-name {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 8px;
  margin-left: 8px;
  vertical-align: middle;
}
.np-name:not([hidden]) ~ #npSubLine {
  display: none;
}
#npNameIn {
  width: 210px;
  min-width: 0;
  min-height: 30px;
  box-sizing: border-box;
  padding: 4px 10px;
  border: 2px solid var(--ink);
  border-radius: 8px;
  background: #fffdf7;
  color: var(--ink);
  font:
    15px/1.2 "Anek Bangla",
    system-ui,
    sans-serif;
  user-select: text;
  -webkit-user-select: text;
}
#npNameIn:focus-visible,
.np-name-go:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 2px;
}
.np-name-go {
  min-height: 30px;
  padding: 5px 12px 2px;
  border: 2px solid var(--ink);
  border-radius: 8px;
  background: var(--hood);
  color: var(--ink);
  font-family: var(--f-display);
  font-weight: 800;
  font-size: 15px;
  line-height: 1.1;
  cursor: pointer;
}
.np-name-go:disabled {
  opacity: 0.6;
}
.np-name-say {
  font-size: 13px;
  font-weight: 700;
  color: #2f6b45;
}
.np-name-say.bad {
  color: #b3121b;
}
.np-name-say:empty {
  display: none;
}
/* the board's browser check (src/game/wanted.js, human): an empty box until Cloudflare asks for a tap, then a small
   card over the paper and the poster */
#check {
  position: absolute;
  left: 50%;
  bottom: calc(env(safe-area-inset-bottom, 0px) + 16px);
  transform: translateX(-50%);
  z-index: 16;
}
#check.ask {
  padding: 10px 12px 12px;
  background: var(--newsprint);
  color: var(--ink);
  border: 3px solid var(--ink);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
}
#check p {
  margin: 0 0 8px;
  font-size: 15px;
  line-height: 1.3;
  text-align: center;
}
#wanted {
  position: absolute;
  inset: 0;
  z-index: 15;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(10, 8, 6, 0.62);
  padding: calc(env(safe-area-inset-top, 0px) + 16px)
    max(16px, env(safe-area-inset-right, 0px))
    calc(env(safe-area-inset-bottom, 0px) + 16px)
    max(16px, env(safe-area-inset-left, 0px));
  box-sizing: border-box;
  touch-action: manipulation;
  touch-action: pan-x pan-y;
  user-select: text;
  -webkit-user-select: text;
}
.w-card {
  position: relative;
  width: 100%;
  max-width: 440px;
  max-height: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 18px 18px 14px;
  background: var(--newsprint);
  color: var(--ink);
  border: 4px solid var(--ink);
  outline: 1.5px solid var(--ink);
  outline-offset: -11px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
  font-family: var(--f-ui);
  text-align: center;
}
.w-card h2 {
  margin: 10px 0 0;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(36px, 10vw, 48px);
  line-height: 1;
  color: #b3121b;
}
.w-lead {
  margin: 0 8px;
  font-size: 14px;
  line-height: 1.45;
}
.w-tabs {
  display: flex;
  justify-content: center;
  gap: 6px;
}
.w-tabs button {
  min-height: 38px;
  padding: 7px 14px 4px;
  border: 2px solid var(--ink);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  font-family: var(--f-display);
  font-weight: 800;
  font-size: 15px;
  line-height: 1.1;
  cursor: pointer;
}
.w-tabs button[aria-selected="true"] {
  background: var(--ink);
  color: var(--newsprint);
}
.w-list {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  margin: 0;
  padding: 0;
  list-style: none;
  text-align: left;
  border-top: 2px solid var(--ink);
}
.w-list li {
  display: grid;
  grid-template-columns: 2em minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 8px;
  padding: 7px 6px 5px;
  border-bottom: 1px dashed rgba(29, 24, 20, 0.35);
  font-size: 16px;
  line-height: 1.3;
}
.w-list li.me {
  background: #ffe08a;
}
.w-list li.w-wait {
  display: block;
  padding: 18px 6px;
  border: 0;
  text-align: center;
  opacity: 0.8;
}
.w-rank {
  font-family: var(--f-display);
  font-weight: 800;
  color: #b3121b;
}
.w-list li:nth-child(-n + 3) .w-rank {
  font-size: 1.25em;
}
.w-who {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 700;
}
.w-who.anon {
  font-weight: 400;
  font-style: italic;
  opacity: 0.7;
}
.w-loss {
  font-family: var(--f-display);
  font-weight: 800;
  white-space: nowrap;
}
.w-me {
  margin: 0;
  font-size: 14px;
  font-weight: 700;
}
.w-name {
  display: grid;
  gap: 6px;
  text-align: left;
}
.w-name label {
  font-size: 13px;
  font-weight: 700;
}
#wNameIn {
  flex: 1 1 160px;
  min-width: 0;
  min-height: 46px;
  box-sizing: border-box;
  padding: 9px 12px;
  border: 2px solid var(--ink);
  border-radius: 10px;
  background: #fffdf7;
  color: var(--ink);
  font:
    16px/1.2 "Anek Bangla",
    system-ui,
    sans-serif;
  user-select: text;
  -webkit-user-select: text;
} /* 16px: smaller, and an iPhone zooms in */
#wNameIn:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 2px;
}
#wNameSend {
  flex: 0 0 auto;
  font-size: 18px;
  min-height: 46px;
  padding: 11px 16px 8px;
  box-shadow:
    0 4px 0 #9c7400,
    0 0 0 2px #000;
}
#wNameSend:disabled {
  opacity: 0.6;
}
.w-fine {
  margin: 0;
  font-size: 12.5px;
  opacity: 0.8;
}
.w-fine a {
  color: inherit;
}
/* inside Facebook, Messenger, Instagram or TikTok (HEALTH.paper): how to get to the phone's own browser, which can share */
.np-inapp {
  flex-basis: 100%;
  margin: 0;
  padding: 7px 10px 6px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  font-size: 14px;
  line-height: 1.45;
  background: #fff3c4;
  border-left: 4px solid #b3121b;
  border-radius: 4px;
}
/* the install offer (INSTALL): a quiet row under the buttons, on phones only, from the second run */
/* the paper's two small buttons beside আবার চালান: Home (back to the title screen) and, on phones, Install (INSTALL);
   an icon over a short word, so on a phone both fit in আবার চালান's row */
.np-home,
.np-install,
.np-share-open,
.np-fb,
.np-ig {
  flex: none;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-width: 60px;
  min-height: 48px;
  margin: 0;
  padding: 4px 10px 3px;
  box-sizing: border-box;
  border: 2px solid var(--ink);
  border-radius: 12px;
  background: #fff8e6;
  color: var(--ink);
  font-family: var(--f-display);
  font-weight: 800;
  font-size: 12.5px;
  line-height: 1.1;
  cursor: pointer;
}
.np-home svg,
.np-install svg,
.np-share-open svg,
.np-fb svg,
.np-ig svg {
  flex: none;
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.np-install svg {
  stroke: #1f8a4c;
}
/* the post to Facebook and the Instagram share (SHARE), rows in the share menu like the picture and the video, with
   Facebook's round blue f and a line-art camera (not Instagram's logo) */
.np-fb {
  text-decoration: none;
}
.np-fb svg {
  fill: #fff;
  stroke: none;
  background: #1877f2;
  border-radius: 50%;
}
.np-ig svg {
  stroke: #c13584;
}
.np-ig svg circle:last-child {
  fill: #c13584;
}
.np-home:active,
.np-install:active,
.np-share-open:active,
.np-fb:active,
.np-ig:active {
  transform: translateY(2px);
}
.np-home:focus-visible,
.np-install:focus-visible,
.np-share-open:focus-visible,
.np-fb:focus-visible,
.np-ig:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 2px;
}
.np-break {
  display: none;
}
/* one শেয়ার (the owner's choice for phones, 23 October 2026: one row of buttons instead of two; on a laptop too since
   27 October, when Facebook and Instagram joined the picture and the video and four did not fit in the row): the ways
   to share in a small menu over the bar, or straight to the one there is (game.js). On a laptop the opener is a text
   button like the old two, and the menu opens over it (--shares-x, set as it opens) */
.np > .np-actions {
  position: relative;
} /* the menu's anchor */
.np-shares {
  position: absolute;
  left: var(--shares-x, 20px);
  bottom: calc(100% + 6px);
  z-index: 3;
  display: none;
  flex-direction: column;
  gap: 8px;
  width: 250px;
  padding: 10px;
  box-sizing: border-box;
  background: var(--newsprint);
  border: 2px solid var(--ink);
  border-radius: 12px;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.4);
}
.np-actions.shares-open .np-shares {
  display: flex;
}
.np-shares .share,
.np-shares .np-fb,
.np-shares .np-ig {
  flex: none;
  width: 100%;
  min-height: 46px;
  padding: 9px 12px 6px;
  border: 2px solid var(--ink);
  border-radius: 12px;
  background: transparent;
  font-size: 19px;
  line-height: 1;
  white-space: nowrap;
}
.np-shares .np-fb,
.np-shares .np-ig {
  flex-direction: row;
  gap: 8px;
}
@media (min-width: 641px) {
  .np > .np-actions {
    bottom: auto;
  } /* the bar's old sticky offset (bottom: -16px) moved it 16 px down once it was relative, off a 768 px screen under a long paper */
  .np-actions .np-share-open {
    flex-direction: row;
    gap: 8px;
    min-height: 48px;
    padding: 10px 18px 8px;
    border-width: 3px;
    background: transparent;
    font-size: 22px;
  }
  .np-actions .np-share-open svg {
    width: 24px;
    height: 24px;
  }
}
.np-install-how {
  flex-basis: 100%;
  margin: 0;
  padding: 6px 10px;
  font-size: 14px;
  line-height: 1.45;
  background: #e7f4ea;
  border-left: 4px solid #1f8a4c;
  border-radius: 4px;
}
.np-actions .np-inapp .share {
  flex: none;
  font-size: 17px;
  min-height: 40px;
  padding: 9px 14px 6px;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
}
.np-inapp.nudge {
  animation: nudge 0.9s ease-out;
}
@keyframes nudge {
  0%,
  40% {
    background: #ffd34d;
    transform: scale(1.02);
  }
  100% {
    background: #fff3c4;
    transform: none;
  }
}
@media (max-width: 640px) {
  .np-actions {
    gap: 8px 10px;
    flex-wrap: wrap;
  }
  /* two rows: আবার চালান across the paper, then the picture and the video side by side */
  /* two rows: আবার চালান with Install and Home, then the picture and the video; the record in small type under them */
  .np-actions .cta {
    flex: 1 1 0;
    min-width: 0;
    order: 1;
    min-height: 48px;
    font-size: 21px;
    padding: 11px 12px 8px;
    box-shadow:
      0 4px 0 #9c7400,
      0 0 0 2px #000;
  }
  .np-actions .np-share-open {
    order: 2;
  }
  .np-install {
    order: 3;
  }
  .np-home {
    order: 4;
  }
  .np-home,
  .np-install,
  .np-share-open {
    min-width: 56px;
    padding-inline: 8px;
  }
  .np-actions .cta {
    white-space: nowrap;
  }
  .np-actions:has(#npInstall:not([hidden])) .cta {
    font-size: 18px;
    padding-inline: 8px;
  } /* four in the row on a narrow phone */
  .np-shares {
    left: auto;
    right: 12px;
    width: min(240px, calc(100% - 24px));
  } /* at the bar's right end, over শেয়ার */
  .np-shares .share {
    flex: none;
    width: 100%;
  }
  .np-shares .np-fb,
  .np-shares .np-ig {
    order: 5;
    min-height: 44px;
    padding: 9px 10px 6px;
    font-size: 17px;
  } /* after the picture and the video, which the row's order puts at 5 */
  .np-actions .share {
    order: 5;
    flex: 1 1 0;
    min-width: 0;
    font-size: 17px;
    min-height: 44px;
    padding: 9px 10px 6px;
    border-width: 2px;
    white-space: nowrap;
  }
  .np-record {
    order: 6;
    flex-basis: 100%;
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    column-gap: 10px;
    margin-top: -2px;
  }
  .np-actions .best {
    font-size: 13px;
  }
  .np-credit-phone {
    display: inline-flex;
    margin-left: auto;
  }
  #npLines .np-credit {
    display: none;
  }
  .np-subline {
    order: 7;
    margin-top: -4px;
    font-size: 13.5px;
  }
  #npLines {
    flex-direction: column;
    align-items: stretch;
  }
  #npWanted:not([hidden]) ~ #npSubLine:not([hidden])::before {
    content: none;
  }
  .np-name {
    display: flex;
    margin: 4px 0 0;
  }
  #npNameIn {
    flex: 1 1 0;
    width: auto;
    font-size: 16px;
    min-height: 40px;
  } /* 16px: smaller, and an iPhone zooms in */
  .np-name-go {
    min-height: 40px;
  }
  .np-name-say {
    flex-basis: 100%;
  }
  .np-install-how {
    order: 8;
  }
  .np-inapp {
    order: 9;
  }
}
@media (max-width: 480px) {
  .np {
    padding: 14px 14px 16px;
  }
  .np-actions {
    margin: 16px -14px -16px;
    padding: 12px 14px 14px;
  }
}

#perf {
  position: absolute;
  top: 38%;
  left: max(4px, env(safe-area-inset-left));
  padding: 3px 6px;
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.55);
  color: #fff;
  font:
    10px/1.35 ui-monospace,
    Menlo,
    Consolas,
    monospace;
  white-space: pre;
  pointer-events: none;
}
/* the loading screen: the name on a painted panel, like the back of a rickshaw, framed in yellow with a pink rule and
   a garland above and below; the line under it breathes, so a slow phone still looks alive */
#loading {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: var(--tar);
}
#loading .ld {
  display: grid;
  justify-items: center;
  gap: 10px;
  width: min(300px, 78vw);
  box-sizing: border-box;
  padding: 14px 16px 16px;
  border-radius: 16px;
  background: #14372f;
  border: 3px solid var(--hood);
  box-shadow:
    0 0 0 3px var(--tar),
    0 0 0 5px var(--led-pink),
    0 18px 50px rgba(0, 0, 0, 0.5);
}
#loading .garland {
  width: 100%;
}
#loading b {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(40px, 13vw, 52px);
  line-height: 1;
  padding-top: 6px;
  color: var(--hood);
  text-shadow:
    3px 3px 0 #ae2941,
    6px 6px 0 #0b211c;
}
#loading .ld span {
  font-family: var(--f-ui);
  font-size: 16px;
  color: var(--paper);
  animation: breathe 1.4s ease-in-out infinite;
}
/* the boot guard's message (see the script after #loading): what went wrong, in plain words, and a retry */
#loading.fail .ld span {
  display: none;
}
#bootMsg {
  margin: 2px 0 4px;
  font-family: var(--f-ui);
  font-size: 16px;
  line-height: 1.5;
  text-align: center;
  color: var(--paper);
}
#bootRetry {
  font-size: 21px;
  padding: 11px 22px 8px;
}
#loading.fail,
#loading.slow {
  z-index: 20;
} /* over the game, when the phone takes its graphics away mid-run */
@keyframes breathe {
  50% {
    opacity: 0.4;
  }
}
@media (prefers-reduced-motion: reduce) {
  #mobWarn,
  #battWarn,
  #blockade,
  #loading .ld span {
    animation: none;
  }
  .np {
    animation: none;
  }
}
.battery-label {
  font-size: 14px;
  color: #183c34;
  background: #fff7e8ed;
  padding: 1px 8px;
  border-radius: 6px;
}
.battery-label strong {
  font-size: 20px;
}
#minimap {
  width: 112px;
  height: 112px;
  border-color: #fff9;
  box-shadow: 0 2px 6px #0003;
} /* 92 px until 25 October 2026: too small to tell its marks apart */
.bar {
  width: 112px;
  height: 7px;
}
@media (max-height: 640px) and (orientation: portrait) {
  #minimap {
    width: 96px;
    height: 96px;
  }
  .bar {
    width: 96px;
