/* ═══ UI polish, hand-added over the build above (1 November 2026) ═══════════════════════════
   Nothing here re-designs the game: the palette, the lettering, the rickshaw paint and every
   screen stay exactly as they were. This layer only sharpens what playing it revealed —
   touch latency, scrollbars, hover and press feedback, contrast, comfort on a narrow phone,
   and the fullscreen switch in the menu's corner (its button is added by the small script at
   the end of the page). Every rule is additive: delete this block and the build is itself. */

/* 1 · a phone's rubber-band scroll or pull-to-refresh must never eat a run */
html,
body {
  overscroll-behavior: none;
}

/* 2 · taps answer at once: no 300 ms wait for a second tap that never comes. The scrollers keep
   their own pan-x pan-y (above), which this does not touch */
button,
summary,
a[href],
.tbtn,
.linkish {
  touch-action: manipulation;
}

/* 3 · selection in the rickshaw's own colours, not the browser's blue */
::selection {
  background: var(--hood);
  color: var(--ink);
}

/* 4 · Bengali headlines break on a balanced line instead of leaving one orphan word */
h1.title,
#pause h2,
.np-name,
.sub-card h2,
.w-card h2,
#npHead,
#npQuoteText,
.sub-lead,
.w-lead {
  text-wrap: balance;
}

/* 5 · scrollbars that belong to the paper and the menu (Chrome on Windows paints a grey slab) */
#menu,
.np-scroll,
.w-list {
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 203, 31, 0.5) rgba(0, 0, 0, 0.3);
}
.np-scroll,
.w-list {
  scrollbar-color: rgba(29, 24, 20, 0.45) rgba(0, 0, 0, 0.08);
}
#menu::-webkit-scrollbar,
.np-scroll::-webkit-scrollbar,
.w-list::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}
#menu::-webkit-scrollbar-track,
.np-scroll::-webkit-scrollbar-track,
.w-list::-webkit-scrollbar-track {
  background: transparent;
}
#menu::-webkit-scrollbar-thumb {
  background: rgba(255, 203, 31, 0.45);
  border-radius: 99px;
}
.np-scroll::-webkit-scrollbar-thumb,
.w-list::-webkit-scrollbar-thumb {
  background: rgba(29, 24, 20, 0.35);
  border-radius: 99px;
}
#menu::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 203, 31, 0.8);
}
.np-scroll::-webkit-scrollbar-thumb:hover,
.w-list::-webkit-scrollbar-thumb:hover {
  background: rgba(29, 24, 20, 0.6);
}

/* 6 · every icon button keeps a 44 px thumb target, whatever the screen */
#pauseBtn,
#muteBtn,
.np-home,
.np-share-open,
.np-install,
.sub-x,
#wClose {
  min-width: 44px;
  min-height: 44px;
}
/* 7 · the mouse gets a real answer: a lift, and the hood's yellow where it belongs. Touch never
   sees these, so no hover state sticks to a finger after a tap */
@media (hover: hover) and (pointer: fine) {
  .cta,
  .np-actions .share,
  .np-home,
  .np-share-open,
  .np-install,
  .fb-page,
  .menu-tube,
  .wanted-tag,
  .menu-fs,
  #muteBtn,
  #pauseBtn,
  .tbtn,
  .w-tabs button,
  .help summary,
  .linkish {
    transition:
      transform 0.1s ease,
      filter 0.14s ease,
      background 0.14s ease,
      box-shadow 0.14s ease,
      color 0.14s ease,
      border-color 0.14s ease;
  }
  .cta:hover,
  .np-actions .share:hover,
  .np-home:hover,
  .np-share-open:hover,
  .np-install:hover {
    transform: translateY(-2px);
    filter: brightness(1.06);
  }
  #playBtn:hover {
    box-shadow:
      0 6px 0 #9c7400,
      0 0 0 3px #000,
      0 12px 30px rgba(255, 203, 31, 0.32);
  }
  .fb-page:hover,
  .menu-tube:hover,
  .menu-fs:hover,
  .wanted-tag:hover {
    transform: translateY(-2px);
    filter: brightness(1.08);
  }
  #muteBtn:hover,
  #pauseBtn:hover,
  .tbtn:hover {
    background: rgba(255, 255, 255, 0.2);
    border-color: #fff;
  }
  .linkish:hover,
  .help summary:hover {
    color: var(--hood);
  }
  .w-tabs button:hover {
    background: rgba(0, 0, 0, 0.08);
  }
  .np-imprint a:hover,
  .w-fine a:hover,
  .sub-fine a:hover {
    color: var(--breaking);
  }
}

/* 8 · reduced motion: the build already stills the crawl, these blinks and pulses join it */
@media (prefers-reduced-motion: reduce) {
  #battWarn,
  #chargeNow.on,
  #placeCard .live::before,
  #ticker .tag::before,
  #mobWarn,
  #blockade,
  #loading .ld span {
    animation: none !important;
  }
  .cta,
  .np-actions .share,
  .np-home,
  .np-share-open,
  .np-install,
  .fb-page,
  .menu-tube,
  .menu-fs,
  .tbtn,
  .help summary {
    transition: none !important;
  }
}

/* 9 · players who ask their system for more contrast get the small print off the street */
@media (prefers-contrast: more) {
  .lbl {
    background: #0a0806;
    box-shadow: inset 0 0 0 1px #fff;
  }
  #ticker .track {
    text-shadow:
      0 1px 2px #000,
      0 0 1px #000;
  }
  #chargeHint {
    background: rgba(8, 6, 5, 0.92);
  }
  .help[open] {
    background: rgba(8, 14, 12, 0.82);
  }
  .menu-note,
  .credit,
  .menu-url,
  .np-meta,
  .np-imprint {
    opacity: 1;
  }
}

/* 10 · a narrow phone (under 360 px): the loss figure and the battery column were touching */
@media (max-width: 359px) {
  #loss {
    font-size: 28px;
  }
  #combo {
    font-size: 17px;
  }
  .lbl {
    font-size: 11px;
  }
  #minimap {
    width: 92px;
    height: 92px;
  }
}

/* 11 · the fullscreen switch, drawn from the Facebook and YouTube buttons beside it. The button
   is added by the script at the end of the page, and only where the browser has the API */
.menu-fs {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  box-sizing: border-box;
  padding: 0;
  border: 2px solid var(--ink);
  border-radius: 50%;
  background: #14372f;
  color: var(--paper);
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}
.menu-fs svg {
  width: 20px;
  height: 20px;
}
.menu-fs span {
  display: none;
}
.menu-fs:active {
  transform: translateY(2px);
}
.menu-fs:focus-visible {
  outline: 3px solid var(--led-cyan);
  outline-offset: 2px;
}
.menu-fs[aria-pressed="true"] {
  border-color: var(--hood);
  color: var(--hood);
}
.menu-fs[hidden] {
  display: none !important;
}
@media (min-width: 760px) and (min-height: 501px) {
  /* the same row as the page's other pills (see the build's own rule at this size) */
  .menu-fs {
    width: auto;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 0 15px 0 10px;
    border-radius: 999px;
    font-size: 15px;
  }
  .menu-fs span {
    display: inline;
    padding-top: 3px;
  }
}

